// Limpia y limita los datos del correo (vienen de fuera, no son de confianza)
// y prepara el texto que se envía a la IA. Lo reciben tanto los correos de Gmail
// como los del formulario de pruebas, y también los reintentos.
const MAX_ASUNTO = 300;
const MAX_MENSAJE = 8000;
const MAX_NOMBRE = 120;
const MAX_EMAIL = 254;

const item = $input.first().json;
const flags = Array.isArray(item.input_flags) ? item.input_flags.filter((f) => typeof f === 'string') : [];
let truncado = false;
let invisibles = false;

// Datos que no hace falta guardar ni enviar a la IA: IBAN, tarjetas, DNI/NIE
const ocultar = (t) =>
  t
    .replace(/\b[A-Z]{2}\d{2}(?:[ ]?[A-Z]{4})?(?:[ ]?(?=[A-Z0-9]{0,3}\d)[A-Z0-9]{4}){2,7}(?:[ ]?\d{1,4})?\b/gi, '[IBAN oculto]')
    .replace(/\b(?:\d[ -]?){12,18}\d\b/g, '[número oculto]')
    .replace(/\b(?:\d{8}|[XYZ]\d{7})-?[A-Z]\b/gi, '[documento oculto]');

// Caracteres que no se ven y sirven para esconder órdenes o romper palabras: ancho cero, marcas de dirección,
// espacios "vacíos" y los caracteres "tag" de Unicode (E0000-E007F, que pueden llevar un mensaje entero invisible)
const INVISIBLES = /[\u{00AD}\u{034F}\u{061C}\u{115F}\u{1160}\u{17B4}\u{17B5}\u{180B}-\u{180E}\u{200B}\u{200C}\u{200E}\u{200F}\u{202A}-\u{202E}\u{2060}-\u{206F}\u{3164}\u{FEFF}\u{FFA0}\u{E0000}-\u{E007F}\u{E0100}-\u{E01EF}]/gu;
// El pegamento de ancho cero y los selectores de variante son normales en los emojis, pero entre letras solo rompen palabras
const ENTRE_LETRAS = /(?<=\p{L})[\u{200D}\u{FE00}-\u{FE0F}]|[\u{200D}\u{FE00}-\u{FE0F}](?=\p{L})/gu;
// Letras y cifras "decoradas" (ancho completo, matemáticas, encerradas) que se leen igual que las normales:
// se pasan a su forma normal para que no esquiven el enmascarado ni las reglas. No se toca nada más (ª, º, …, ½)
const DECORADAS = /[\u{FF00}-\u{FFEF}\u{2460}-\u{24FF}\u{1D400}-\u{1D7FF}\u{1F100}-\u{1F1FF}]+/gu;
// Espacios raros (no separable, ancho completo...) a un espacio normal: así no esquivan el enmascarado
const ESPACIOS = /[\u{00A0}\u{1680}\u{2000}-\u{200A}\u{202F}\u{205F}\u{3000}]/gu;
const CONTROL = /[\u{0000}-\u{0008}\u{000B}\u{000C}\u{000E}-\u{001F}\u{007F}]/gu;

const limpiar = (valor, max, { enmascarar = true, linea = false } = {}) => {
  let s = String(valor ?? '');
  const antes = s;
  s = s.replace(INVISIBLES, '').replace(ENTRE_LETRAS, '');
  if (s !== antes) invisibles = true;
  s = s.replace(DECORADAS, (m) => m.normalize('NFKC')).replace(ESPACIOS, ' ').replace(CONTROL, '');
  if (linea) s = s.replace(/[\t\r\n\u{2028}\u{2029}]+/gu, ' ');
  if (s.length > max * 4) { s = s.slice(0, max * 4); truncado = true; }
  s = (enmascarar ? ocultar(s) : s).trim();
  if (s.length > max) { s = s.slice(0, max) + ' […]'; truncado = true; }
  return s;
};

let Asunto = limpiar(item.Asunto, MAX_ASUNTO, { linea: true });
const Mensaje = limpiar(item.Mensaje, MAX_MENSAJE);
const Nombre = limpiar(item.Nombre, MAX_NOMBRE, { linea: true });
let Email = limpiar(item.Email, MAX_EMAIL, { enmascarar: false, linea: true }); // la dirección del remitente no se enmascara: hace falta para el borrador

if (!Asunto) { Asunto = '(sin asunto)'; flags.push('Correo sin asunto'); }
if (!Mensaje) flags.push('Correo sin texto');
// Una sola dirección, sin comas, comillas ni paréntesis: así el destinatario del borrador no puede llevar nada más
if (!/^[\p{L}\p{N}._%+'-]+@[\p{L}\p{N}-]+(?:\.[\p{L}\p{N}-]+)+$/u.test(Email)) {
  Email = '';
  flags.push('Remitente sin dirección de correo válida');
}
if (truncado) flags.push('Correo recortado por tamaño');
if (invisibles) flags.push('Texto con caracteres invisibles (eliminados)');
if (/[A-Za-z][Ͱ-ϿЀ-ӿ]|[Ͱ-ϿЀ-ӿ][A-Za-z]/.test(Asunto + ' ' + Mensaje + ' ' + Nombre)) {
  flags.push('Palabras con letras de alfabetos mezclados');
}

// Se quitan < y > del texto que va a la IA: así nadie puede cerrar la etiqueta <correo> ni abrir otra
const plano = (t) => t.replace(/[<>]/g, ' ');
const email_text =
  'Analiza el siguiente correo.\n\n<correo>\n' +
  'De: ' + plano(Nombre) + ' <' + plano(Email) + '>\n' +
  'Asunto: ' + plano(Asunto) + '\n' +
  'Mensaje: ' + plano(Mensaje) + '\n</correo>';

return [{ json: { ...item, Nombre, Email, Asunto, Mensaje, input_flags: [...new Set(flags)], email_text } }];

const original = $('Preparar petición IA').first().json;
const r = $input.first().json || {};

// Formato de OpenAI/Groq o de Gemini
const raw = r.choices?.[0]?.message?.content ?? r.candidates?.[0]?.content?.parts?.[0]?.text;

let ai = {};
let parse_error = false;
let api_error = '';

if (typeof raw === 'string' && raw.trim() !== '') {
  try {
    const parsed = JSON.parse(raw);
    // Tiene que ser un objeto: null, una lista o un texto no valen
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) ai = parsed;
    else parse_error = true;
  } catch (e) {
    parse_error = true;
  }
} else {
  parse_error = true;
  // Si el nodo de la API falló (tras sus reintentos) devuelve { error: ... } en vez de una respuesta
  if (r.error) {
    // n8n añade "details" con el código HTTP y un mensaje legible; si no está, se usa el propio error
    const d = r.details && r.details.message ? r.details : null;
    const legible = d ? (d.httpCode ? d.httpCode + ' - ' : '') + d.message + (d.description ? ': ' + d.description : '') : '';
    const motivo = legible || (typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error)));
    api_error = String(motivo)
      .replace(/(bearer\s+)\S+|gsk_\w+/gi, '[oculto]')
      .replace(/\s+/g, ' ')
      .slice(0, 300);
  }
}

return [{ json: { ...ai, ...original, parse_error, api_error } }];

// La IA propone; este código decide. Nada de lo que devuelve el modelo llega al borrador sin pasar por aquí.
const d = $input.first().json;

const categorias = ['presupuesto', 'informacion', 'pedido', 'reclamacion', 'otra'];
const prioridades = ['baja', 'media', 'alta'];
const camposTexto = ['category', 'priority', 'customer_name', 'company', 'requested_service', 'quantity', 'summary', 'draft_reply'];

const errores = [];
const avisos = [];

// 1. ¿La respuesta de la IA tiene la forma correcta?
if (d.api_error) {
  errores.push('Fallo al llamar a la IA: ' + d.api_error);
} else if (d.parse_error) {
  errores.push('La IA no devolvió un JSON legible');
} else {
  for (const campo of camposTexto) {
    if (typeof d[campo] !== 'string') errores.push('Falta o no es texto: ' + campo);
  }
  if (!Array.isArray(d.missing_information) || d.missing_information.some(x => typeof x !== 'string')) {
    errores.push('missing_information debe ser una lista de textos');
  }
  if (typeof d.human_review_required !== 'boolean') {
    errores.push('human_review_required debe ser true o false');
  }
  if (!categorias.includes(d.category)) errores.push('Categoría no permitida: ' + d.category);
  if (!prioridades.includes(d.priority)) errores.push('Prioridad no permitida: ' + d.priority);
}

const valido = errores.length === 0;
let priority = valido ? d.priority : '';
let revision = valido ? d.human_review_required : true;

// 2. Reglas sobre el correo, se aplican siempre
// Para buscar órdenes se mira una copia "aplanada" del texto (letras decoradas y parecidas pasadas a normales):
// el texto original no se toca.
const PARECIDAS = {
  'а': 'a', 'е': 'e', 'о': 'o', 'р': 'p', 'с': 'c', 'у': 'y', 'х': 'x', 'і': 'i', 'ј': 'j', 'ѕ': 's', 'ԁ': 'd', 'һ': 'h', 'ԛ': 'q', 'ѵ': 'v',
  'А': 'A', 'В': 'B', 'Е': 'E', 'К': 'K', 'М': 'M', 'Н': 'H', 'О': 'O', 'Р': 'P', 'С': 'C', 'Т': 'T', 'Х': 'X',
  'Α': 'A', 'Β': 'B', 'Ε': 'E', 'Ζ': 'Z', 'Η': 'H', 'Ι': 'I', 'Κ': 'K', 'Μ': 'M', 'Ν': 'N', 'Ο': 'O', 'Ρ': 'P', 'Τ': 'T', 'Υ': 'Y', 'Χ': 'X',
  'ο': 'o', 'ν': 'v', 'ι': 'i', 'υ': 'u',
};
const INVISIBLES = /[\u{00AD}\u{034F}\u{061C}\u{115F}\u{1160}\u{17B4}\u{17B5}\u{180B}-\u{180F}\u{200B}-\u{200F}\u{202A}-\u{202E}\u{2060}-\u{206F}\u{3164}\u{FE00}-\u{FE0F}\u{FEFF}\u{FFA0}\u{E0000}-\u{E007F}\u{E0100}-\u{E01EF}]/gu;
const HAY_INVISIBLES = new RegExp(INVISIBLES.source, 'u'); // sin la marca "g": con ella, .test() recuerda la posición anterior
const aplanar = (t) =>
  String(t || '')
    .replace(INVISIBLES, '')
    .normalize('NFKC')
    .replace(/[Ͱ-ϿЀ-ӿ]/g, (c) => PARECIDAS[c] || c);

const textoCliente = aplanar([d.Asunto, d.Mensaje, d.Nombre].join('\n'));

// Avisos de la preparación del correo (sin asunto, sin texto, recortado, remitente no válido...)
const avisosEntrada = Array.isArray(d.input_flags) ? d.input_flags.filter(x => typeof x === 'string') : [];
if (avisosEntrada.length > 0) {
  revision = true;
  avisos.push(...avisosEntrada);
}

// Órdenes dirigidas a la IA (español e inglés). Cada grupo tiene un nombre para que la persona que revisa
// vea qué se detectó. Son reglas de texto: reducen el riesgo, no lo eliminan (véase KNOWN_LIMITATIONS.md).
const ORDENES = [
  ['ignorar instrucciones', /ignor[ae]\s+(tus|las|todas)|instrucciones anteriores|ignore\s+(all|your|previous)|system prompt|prompt del sistema|olvida\s+(todo|tus|las)/i],
  ['ignorar instrucciones', /ignor\w*\s+(?:\w+\s+){0,3}?(?:instrucciones|reglas|indicaciones|normas|directrices|restricciones|políticas|prompt)|\b(?:ignore|disregard|bypass|override)\s+(?:\w+\s+){0,3}?(?:instructions?|rules|guidelines|restrictions|polic(?:y|ies)|prompts?)|\bforget\s+(?:everything|all|your|the\s+(?:rules|instructions))|olvida\s+lo\s+(?:anterior|que)/i],
  ['cambio de rol', /(?:act[uú]a|comp[oó]rtate|finge|pretende|haz\s+de\s+cuenta|imagina\s+que\s+eres)\s+(?:como|ser|que)\b|\b(?:you\s+are\s+now|ahora\s+eres|pretend\s+(?:to\s+be|you)|act\s+as|role-?play|jailbreak|developer\s+mode|modo\s+(?:desarrollador|dios|sin\s+restricciones))|(?:a\s+partir\s+de\s+ahora|de\s+ahora\s+en\s+adelante|from\s+now\s+on)\s*,?\s*(?:t[uú]\s+|you\s+)?(?:responde|contesta|eres|act[uú]a|debes|tienes|obedece|respond|answer|act|must|will|are|only)\b/i],
  ['mensaje de sistema', /(?:^|\n)\s*(?:system|sistema|assistant|asistente|developer|desarrollador)\s*:|\[\/?(?:system|inst|sys)\]|<\|?(?:system|im_start|im_end|endoftext)|#{2,}\s*(?:system|instruction|instrucci)|```\s*(?:system|json)/i],
  ['pedir el prompt', /(?:system|sistema|initial|inicial|hidden|oculto|your|tu|el|the)\s+prompt\b|prompt\s+(?:del\s+sistema|inicial|oculto|original)|instrucciones\s+(?:del\s+sistema|internas|iniciales|ocultas|que\s+te\s+(?:han\s+)?(?:dado|dieron))|tus\s+instrucciones|your\s+(?:system\s+)?(?:instructions|rules)/i],
  ['órdenes sobre la respuesta', /\b(?:human_review_required|draft_reply|can_draft|missing_information|json_schema|response_format)\b|\b(?:priority|prioridad)\b["']?\s*[:=]\s*["']?(?:alta|media|baja|high|low|urgent)|\b(?:responde|contesta|escribe|di|dile|answer|reply|say|tell\s+(?:him|her|them|the\s+customer))\s+(?:al\s+cliente\s+)?(?:que|solo|solamente|únicamente|exactamente|only|exactly|that)\b|\bpromete(?:s|r)?\s+\w+|\bprometa\s+\w+|\bapprove\s+(?:the\s+)?(?:refund|discount|payment|order)|\bpromise\s+(?:the\s+)?(?:customer|delivery|refund)|(?:marca|clasifica|pon|mark|classify|set)\s+(?:esto|este\s+correo|el\s+correo|it|this)\s+(?:como|as)\s+(?:prioridad\s+)?(?:alta|urgente|high|urgent)/i],
  ['sacar datos', /(?:reenv\w*|forward|exporta\w*|export|env[ií]a|send|manda|filtra|leak)\s+(?:\w+\s+){0,5}?(?:historial|todos\s+los\s+(?:correos|mensajes|clientes|contactos)|bandeja|inbox|base\s+de\s+datos|database|lista\s+de\s+clientes|contactos|customer\s+(?:list|data)|credenciales|credentials|api\s*key|contrase[ñn]a|password|token)|\b(?:bcc|cco)\b|copia\s+oculta/i],
  ['falsa autoridad', /(?:mensaje|orden|instrucci[oó]n)\s+(?:del|de\s+parte\s+del)\s+(?:sistema|administrador\s+del\s+sistema|desarrollador)|\b(?:message|order|instruction)\s+from\s+the\s+(?:system|developer|administrator)|soy\s+(?:el|tu)\s+(?:administrador|desarrollador|creador)\s+del\s+(?:sistema|bot|asistente|flujo)|i\s+am\s+(?:your|the)\s+(?:developer|administrator|creator)|\b(?:openai|anthropic|groq|n8n)\s+(?:team|support|staff|equipo)/i],
  ['sin restricciones', /sin\s+(?:ninguna\s+)?(?:restricci|filtro|l[ií]mite|censura)|without\s+(?:any\s+)?(?:restrictions|filters|limits|censorship)|you\s+have\s+no\s+(?:restrictions|rules)/i],
  ['texto codificado', /(?:decodifica|decode|descifra|decrypt)\w*\s+(?:\w+\s+){0,5}?(?:y\s+)?(?:sigue|obedece|ejec[uú]t\w*|follow|obey|execute|run)|[A-Za-z0-9+/]{160,}/i],
  ['etiquetas o enlaces activos', /<\s*\/?\s*(?:script|iframe|tool|function|system|instructions?)\b|\b(?:function_call|tool_use|tool_calls)\b|javascript:|data:text\/html/i],
];
const detectadas = [...new Set(ORDENES.filter(([, re]) => re.test(textoCliente)).map(([nombre]) => nombre))];
let manipulacion = detectadas.length > 0;
if (manipulacion) {
  revision = true;
  avisos.push('Posible intento de manipulación en el correo');
  avisos.push('Patrones detectados: ' + detectadas.join(', '));
}
if (/\[(?:número|iban) oculto\]|\b(iban|cvv|cvc)\b|contraseña|número de tarjeta|datos de (la )?tarjeta|tarjeta de (crédito|débito)/i.test(textoCliente)) {
  revision = true;
  avisos.push('El correo contiene datos de pago o credenciales');
}
if (/\[documento oculto\]/.test(textoCliente)) {
  revision = true;
  avisos.push('El correo contiene un documento de identidad (ocultado)');
}

// 3. Reglas sobre la respuesta, solo si es válida
const riesgos = []; // motivos por los que el borrador del modelo NO se puede usar
const textoSeguro = (v, max) =>
  typeof v === 'string'
    ? v.replace(INVISIBLES, '').replace(/[\u{0000}-\u{001F}\u{007F}\u{2028}\u{2029}]+/gu, ' ').replace(/\s+/g, ' ').trim().slice(0, max)
    : '';
let borrador = valido ? d.draft_reply : '';
let camposExtraidos = { customer_name: '', company: '', requested_service: '', quantity: '', missing_information: [] };

if (valido) {
  camposExtraidos = {
    customer_name: textoSeguro(d.customer_name, 120),
    company: textoSeguro(d.company, 120),
    requested_service: textoSeguro(d.requested_service, 200),
    quantity: textoSeguro(d.quantity, 60),
    missing_information: d.missing_information.map((x) => textoSeguro(x, 120)).filter(Boolean).slice(0, 8),
  };
  if (d.category === 'reclamacion') {
    priority = 'alta';
    revision = true;
    avisos.push('Reclamación: prioridad alta y revisión obligatoria');
  }
  // Si el correo da órdenes a la IA, la prioridad no puede salir de esas órdenes:
  // la fija el código según la categoría
  if (manipulacion && d.category !== 'reclamacion') {
    const porDefecto = { presupuesto: 'media', pedido: 'media', informacion: 'baja', otra: 'baja' };
    const fijada = porDefecto[d.category];
    if (fijada && priority !== fijada) {
      avisos.push('Prioridad fijada por el código (' + fijada + '): el correo intenta dar órdenes a la IA');
    }
    if (fijada) priority = fijada;
  }
  if (d.category === 'informacion') {
    revision = true;
    avisos.push('Consulta de información: debe responderla una persona con datos de la empresa');
  }
  if (d.missing_information.length > 0) {
    avisos.push('Información incompleta');
  }
  if (d.draft_reply.trim() === '') {
    revision = true;
    avisos.push('El borrador está vacío: no se crea borrador');
  }
  const regla = (cumple, mensaje) => {
    if (cumple) { revision = true; avisos.push(mensaje); riesgos.push(mensaje); }
  };
  const bd = aplanar(borrador);
  regla(/\d+\s?%|€|\$|\beuros?\b|descuento|gratis|gratuit|garant(?:[ií]a|iz)|precio|tarifas?|cat[aá]logo|promoci[oó]n|\bofertas?\b/i.test(borrador), 'El borrador menciona precios, descuentos o garantías');
  regla(/asegur|antes del|antes de que|en \d+ (días|horas|semanas)|para el (lunes|martes|miércoles|jueves|viernes|sábado|domingo)/i.test(borrador), 'El borrador menciona plazos o fechas de entrega');
  regla(/\b\d{1,2}[:.]\d{2}\b|\bde (lunes|martes|miércoles|jueves|viernes|sábado|domingo) a (lunes|martes|miércoles|jueves|viernes|sábado|domingo)/i.test(borrador), 'El borrador afirma datos de la empresa (horarios u otros)');
  regla(/disponemos|tenemos (disponible|en stock|existencias)|hay (stock|existencias|disponibilidad)|en stock|stock disponible/i.test(borrador), 'El borrador afirma disponibilidad o existencias');
  regla(/\b(sí,?|si,)\s+(ofrecemos|hacemos|realizamos|imprimimos|fabricamos|vendemos|trabajamos|enviamos)|(?<!\bsi\s)\b(ofrecemos|imprimimos|fabricamos|vendemos)\s+(el |la |los |las |un |una )?\w+/i.test(borrador), 'El borrador afirma que la empresa ofrece un producto o servicio');
  // Un correo malicioso puede intentar que el borrador lleve un enlace o una dirección ajena
  regla(/https?:\/\/|www\.|\b[\w.+-]+@[\w-]+\.[\w.-]+/i.test(bd), 'El borrador contiene un enlace o una dirección de correo');
  regla(/<\/?[a-z!][^>]*>|&[a-z]+;|\]\([^)]*\)|```|\bdata:|javascript:|vbscript:|\{\{|\}\}|\$\{/i.test(bd), 'El borrador contiene marcas, enlaces ocultos o código');
  regla(HAY_INVISIBLES.test(borrador) || /[\u{0000}-\u{0008}\u{000B}\u{000C}\u{000E}-\u{001F}\u{007F}]/u.test(borrador), 'El borrador contiene caracteres invisibles o de control');
  // Información inventada: el modelo no conoce precios, plazos ni datos de la empresa, así que toda cifra que
  // no venga del correo (salvo la numeración de una lista) es sospechosa
  const numeros = (t) => (t.match(/\d[\d.,]*\d|\d/g) || []).map((n) => n.replace(/[.,]+$/, ''));
  const delCorreo = new Set(numeros(textoCliente));
  const inventadas = numeros(bd.replace(/^\s*\d+[.)]\s+/gm, '')).filter((n) => !delCorreo.has(n));
  regla(inventadas.length > 0, 'El borrador contiene cifras que no aparecen en el correo');
  regla(/(?:hemos|ha\s+sido|queda|est[aá])\s+(?:\w+\s+)?(?:confirmad|aprobad|aceptad|autorizad|reservad)\w*|\ble\s+(?:reembols|devolver|abonar|compensar|indemniz)\w*|reembolso|indemnizaci|compensaci[oó]n|cancelad[oa]|anulad[oa]|enviad[oa]\s+(?:hoy|ya)|en\s+camino/i.test(bd), 'El borrador promete o confirma algo en nombre de la empresa');
  regla(/tarjeta|\biban\b|\bcvv\b|\bcvc\b|contraseña|password|cuenta\s+bancaria|n[uú]mero\s+de\s+cuenta|transferencia|bizum|paypal|pago\s+(?:anticipado|por\s+adelantado)|datos\s+bancarios/i.test(bd), 'El borrador habla de pagos, cuentas o contraseñas');
  regla(/system\s*prompt|prompt\s+del\s+sistema|instrucciones\s+(?:del\s+sistema|internas)|modelo\s+de\s+lenguaje|language\s+model|inteligencia\s+artificial|como\s+(?:una\s+)?ia\b|as\s+an\s+ai\b|chatgpt|\bgroq\b|openai|\bjson\b|draft_reply|human_review|<\/?correo>|reglas\s+(?:internas|del\s+sistema)|\bn8n\b/i.test(bd), 'El borrador revela detalles internos o habla de la IA');
  regla(borrador.length > 1500 || (borrador.match(/\n/g) || []).length > 30, 'El borrador es demasiado largo');
  // El resumen y los campos extraídos solo los leen personas, pero un enlace ahí también merece atención
  const extraidos = [d.summary, camposExtraidos.customer_name, camposExtraidos.company, camposExtraidos.requested_service, camposExtraidos.quantity, ...camposExtraidos.missing_information].join('\n');
  if (/https?:\/\/|www\./i.test(aplanar(extraidos))) {
    revision = true;
    avisos.push('El resumen o los datos extraídos contienen un enlace');
  }
}

// El borrador del modelo solo se usa si no hay ninguna señal de riesgo. Si la hay, se sustituye por una plantilla
// fija del código (sin cifras, enlaces ni promesas) y una persona escribe lo que haga falta.
const sustituir = valido && borrador.trim() !== '' && (manipulacion || riesgos.length > 0);
if (sustituir) {
  const primerNombre = /^[\p{L}\p{M}][\p{L}\p{M}'’. -]{0,59}$/u.test(d.Nombre || '') ? String(d.Nombre).split(/\s+/)[0] : '';
  borrador =
    (primerNombre ? 'Hola ' + primerNombre + ',' : 'Hola,') +
    '\n\nGracias por escribirnos. Hemos recibido su mensaje y un compañero lo revisará y le responderá lo antes posible.' +
    '\n\nUn saludo,\nEquipo comercial';
  revision = true;
  avisos.push('Borrador sustituido por una plantilla segura (' + (manipulacion ? 'el correo intenta manipular a la IA' : 'el borrador del modelo no era seguro') + ')');
}

// 4. Estado final
let status = 'pendiente_revision';
if (d.api_error) status = 'error_ia';
else if (!valido) status = 'error_validacion';
else if (d.missing_information.length > 0) status = 'incompleta';

// 5. ¿Se puede crear un borrador? Solo con una respuesta válida, con texto y con destinatario
const can_draft = valido && borrador.trim() !== '' && /@/.test(d.Email || '');

return [{
  json: {
    ...d,
    ...camposExtraidos,
    draft_reply: borrador,
    category: valido ? d.category : '',
    summary: valido ? textoSeguro(d.summary, 2000) : '',
    priority,
    human_review_required: revision,
    valid: valido,
    validation_errors: errores,
    // La hoja guarda esta lista: primero el motivo del error (si lo hay) y después los avisos
    validation_flags: [...errores.map(e => 'Error: ' + e), ...avisos],
    can_draft,
    status
  }
}];

// Convierte cada correo de Gmail al formato común del flujo.
// Aquí solo se extrae y se normaliza la forma. Ocultar datos y limitar tamaños
// lo hace "Preparar petición IA", que también recibe los correos del formulario de pruebas.
const aTexto = (t) => (typeof t === 'string' ? t : '');

// Si el correo viene solo en HTML, se convierte a texto plano. Se recorre una sola vez, sin expresiones
// regulares anidadas (un HTML mal formado a propósito no puede colgar el nodo), y se descarta lo que
// una persona no vería: comentarios, <script>, <style> y elementos ocultos con CSS.
const VACIAS = new Set(['br', 'hr', 'img', 'input', 'meta', 'link', 'area', 'base', 'col', 'embed', 'source', 'track', 'wbr']);
const SIEMPRE_FUERA = new Set(['script', 'style', 'template']);
const BLOQUE = /^(?:p|div|li|tr|h[1-6]|ul|ol|table|blockquote|section|article)$/i;
const OCULTO = /display\s*:\s*none|visibility\s*:\s*hidden|font-size\s*:\s*0(?![.\d]*[1-9])|opacity\s*:\s*0(?![.\d]*[1-9])|mso-hide\s*:\s*all|\shidden(?=[\s>=/])/i;
const MAX_ETIQUETA = 2000;

const htmlATexto = (entrada) => {
  const h = aTexto(entrada).slice(0, 200000);
  let salida = '';
  let i = 0;
  let oculto = false;
  let presupuesto = h.length * 4; // tope de trabajo para saltar elementos ocultos: un HTML hostil no puede hacerlo cuadrático
  while (i < h.length) {
    const lt = h.indexOf('<', i);
    if (lt < 0) { salida += h.slice(i); break; }
    salida += h.slice(i, lt);
    if (h.startsWith('<!--', lt)) {
      const fin = h.indexOf('-->', lt + 4);
      if (h.slice(lt + 4, fin < 0 ? h.length : fin).trim() !== '') oculto = true;
      i = fin < 0 ? h.length : fin + 3;
      continue;
    }
    const gt = h.indexOf('>', lt);
    if (gt < 0 || gt - lt > MAX_ETIQUETA) { salida += ' '; i = lt + 1; continue; } // un "<" suelto no es una etiqueta
    const etiqueta = h.slice(lt, gt + 1);
    const m = /^<(\/?)([a-z][a-z0-9]*)/i.exec(etiqueta);
    i = gt + 1;
    if (!m) { salida += ' '; continue; }
    const cierre = m[1] === '/';
    const nombre = m[2].toLowerCase();
    const autocerrada = /\/\s*>$/.test(etiqueta) || VACIAS.has(nombre);
    if (!cierre && !autocerrada && (SIEMPRE_FUERA.has(nombre) || OCULTO.test(etiqueta))) {
      // Se salta todo el elemento, contando los anidados con el mismo nombre
      let profundidad = 1;
      let j = i;
      while (profundidad > 0) {
        const a = h.indexOf('<', j);
        if (a < 0 || presupuesto <= 0) { j = -1; break; }
        const b = h.indexOf('>', a);
        presupuesto -= (b < 0 ? h.length : b) - j + 1;
        if (b < 0 || b - a > MAX_ETIQUETA) { j = a + 1; continue; }
        const t = /^<(\/?)([a-z][a-z0-9]*)/i.exec(h.slice(a, b + 1));
        if (t && t[2].toLowerCase() === nombre && !/\/\s*>$/.test(h.slice(a, b + 1))) profundidad += t[1] === '/' ? -1 : 1;
        j = b + 1;
      }
      if (!SIEMPRE_FUERA.has(nombre)) oculto = true;
      if (j >= 0) i = j;
      else if (SIEMPRE_FUERA.has(nombre)) i = h.length; // <script> o <style> sin cerrar: se descarta el resto
      continue;
    }
    salida += nombre === 'br' || (cierre && BLOQUE.test(nombre)) ? '\n' : ' ';
  }
  const texto = salida
    .replace(/&nbsp;/gi, ' ')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/gi, '&')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n');
  return { texto, oculto };
};

// Identificador de reserva, determinista (el mismo correo da siempre el mismo), por si Gmail no lo trae
const huella = (t) => {
  let h = 5381;
  for (let i = 0; i < t.length; i++) h = ((h * 33) ^ t.charCodeAt(i)) >>> 0;
  return h.toString(16);
};

return $input.all().map((entrada) => {
  const m = entrada.json || {};
  const remitente = (m.from && m.from.value && m.from.value[0]) || {};
  const flags = [];

  let texto = aTexto(m.text).trim();
  if (!texto) {
    const convertido = htmlATexto(m.html || m.textAsHtml);
    texto = convertido.texto.trim();
    if (convertido.oculto) flags.push('El HTML del correo tenía texto oculto (eliminado)');
  }
  const fecha = aTexto(m.date) || new Date().toISOString();

  let id = m.id ? String(m.id) : '';
  if (!id) {
    id = 'sin-id-' + huella(aTexto(remitente.address) + '|' + fecha + '|' + aTexto(m.subject) + '|' + texto.slice(0, 200));
    flags.push('Correo sin identificador de Gmail: se generó uno propio');
  }

  return {
    json: {
      request_id: id,
      received_at: fecha,
      Nombre: aTexto(remitente.name) || aTexto(remitente.address),
      Email: aTexto(remitente.address),
      Asunto: aTexto(m.subject),
      Mensaje: texto,
      input_flags: flags,
      status: 'recibida',
    },
  };
});

