// Step 1 of the lock. Builds the claim for the e-mail of this iteration; the next node writes it
// to the shared "bloqueos" tab. Nothing else is changed: the e-mail travels on untouched.
const item = $input.first().json;
if (!item.request_id) {
  throw new Error('El correo no tiene request_id: no se puede reservar ni procesar');
}
const nowMs = $now.toMillis();
const claimId = `${$execution.id}-${nowMs}-${Math.random().toString(36).slice(2, 8)}`;
return [{ json: { ...item, claim_id: claimId, claim_at: new Date(nowMs).toISOString() } }];

// Step 3 of the lock. Decides whether THIS execution may process the e-mail.
//
// The "bloqueos" tab is an append-only log: an execution writes a "claim" row before it works and a
// "release" row when it is done. Every execution reads the rows of the same request_id in the same
// order (the order the server stored them), so all of them agree on who came first:
//   - a claim is ACTIVE until a release row with the same claim_id appears, or it is older than STALE_MS
//     (a run that died without releasing must not block the e-mail forever);
//   - the FIRST active claim wins; everybody else steps aside.
// If our own claim is not in the list we cannot know who won, so we stop with an error instead of guessing.
const STALE_MS = 10 * 60 * 1000;

const mine = $('Preparar reserva').first().json;
const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && String(r.request_id) === String(mine.request_id))
  .sort((a, b) => (Number(a.row_number) || 0) - (Number(b.row_number) || 0));

if (!rows.some((r) => r.event === 'claim' && r.claim_id === mine.claim_id)) {
  throw new Error('La reserva propia no aparece en la pestaña bloqueos: se detiene el correo para no duplicar borradores');
}

const released = new Set(rows.filter((r) => r.event === 'release').map((r) => r.claim_id));
const reference = Date.parse(mine.claim_at);
const active = rows.filter(
  (r) => r.event === 'claim' && !released.has(r.claim_id) && reference - Date.parse(r.at) < STALE_MS,
);
const winner = active[0];

return [{
  json: {
    ...mine,
    claim_won: !!winner && winner.claim_id === mine.claim_id,
    claim_holder: winner ? winner.claim_id : null,
  },
}];
